  function available(hero){return items.filter(i=>!i.only||i.only===hero);}
  function phrase(itemId,colorId){const item=byId[itemId],color=palette.find(p=>p.id===colorId);return {mn:color?color.mn+' '+item.mn:item.mn,ru:color?color.forms[['m','f','n','pl'].indexOf(item.grammar)]+' '+item.ru:item.ru};}
  window.WARDROBE={items,byId,palette,basePalette,icon,garment,art,avatar,available,phrase};
